import{_ as i,o as l,c as o,ag as d}from"./chunks/framework.D9ghT4bC.js";const p=JSON.parse('{"title":"Unique 参数详解","description":"","frontmatter":{"title":"Unique 参数详解"},"headers":[],"relativePath":"zh/Modders/Unique-parameters.md","filePath":"zh/Modders/Unique-parameters.md"}'),c={name:"zh/Modders/Unique-parameters.md"};function t(a,e,r,n,u,s){return l(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="unique-参数详解" tabindex="-1">Unique 参数详解 <a class="header-anchor" href="#unique-参数详解" aria-label="Permalink to &quot;Unique 参数详解&quot;">​</a></h1><p>本页面包含 uniques 中使用的所有不同参数的概述以及可以填充到它们中的值。 下面描述了每个不同的参数类型，包括它们的所有可能值。 这些分为两类：</p><ul><li>描述：例如，&quot;任何单位的名称&quot;</li><li><code>像这样的文本</code>。最后一个必须完全相同使用</li></ul><p>请注意，所有这些都区分大小写！</p><h2 id="通用过滤器规则" tabindex="-1">通用过滤器规则 <a class="header-anchor" href="#通用过滤器规则" aria-label="Permalink to &quot;通用过滤器规则&quot;">​</a></h2><p>除了 <code>populationFilter</code> 和 <code>resourceFilter</code> 之外的所有过滤器都接受格式为 <code>{A} {B} {C}</code> 等的多个值，意味着&quot;对象必须匹配所有这些过滤器&quot;</p><blockquote><p>示例：<code>[{Military} {Water}] units</code>，<code>[{Wounded} {Armor}] units</code> 等。</p></blockquote><p><code>[</code> 和第一个 <code>{</code> 之间，或最后一个 <code>}</code> 和结束 <code>]</code> 之间不允许有空格或其他文本。但是，<code>} {</code> 中的空格是强制性的。</p><p>所有过滤器都接受 <code>non-[filter]</code> 作为可能的值</p><blockquote><p>示例：<code>[non-[Wounded]] units</code></p></blockquote><p>这些可以通过嵌套组合，除了&quot;ALL&quot;过滤器不能包含另一个&quot;ALL&quot;过滤器，即使中间有 NON 过滤器。</p><blockquote><p>示例：<code>[{non-[Wounded]} {Armor}] units</code> 意味着单位是类型 Armor 并且满生命值。 示例：<code>[non-[{Wounded} {Armor}]] units</code> 意味着单位既不是受伤的也不是 Armor 单位。</p></blockquote><p><code>[{non-[{Wounded} {Armor}]} {Embarked}] units</code> 将失败，因为游戏将同时处理两个&quot;} {&quot;并看到 <code>non-[{Wounded</code> 和 <code>Armor}]</code>，两者都无效。</p><p>Civilopedia 中复杂过滤器的显示可能会变得不可读。如果是这样，考虑隐藏该 unique 并使用 <code>Comment []</code> unique 单独提供更好的措辞。</p><h2 id="civfilter" tabindex="-1">civFilter <a class="header-anchor" href="#civfilter" aria-label="Permalink to &quot;civFilter&quot;">​</a></h2><p>允许过滤特定的文明。</p><p>允许的值：</p><ul><li><code>Human player</code></li><li><code>AI player</code></li><li><code>Friendly</code></li><li><code>Hostile</code></li><li><code>Open Borders</code></li><li><code>Known</code> - 意识到相关文明的文明。Known 包括自己。</li><li><a href="#nationfilter">nationFilter</a></li></ul><h2 id="nationfilter" tabindex="-1">nationFilter <a class="header-anchor" href="#nationfilter" aria-label="Permalink to &quot;nationFilter&quot;">​</a></h2><p>允许过滤特定的文明。由 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#modoptions-json">ModOptions.nationsToRemove</a>使用。</p><p>允许的值：</p><ul><li><code>All</code>，<code>all</code></li><li><code>City-States</code>，<code>City-State</code></li><li><code>Major</code></li><li>文明名称</li><li>文明拥有的 unique（逐字，没有占位符）</li></ul><h2 id="baseunitfilter" tabindex="-1">baseUnitFilter <a class="header-anchor" href="#baseunitfilter" aria-label="Permalink to &quot;baseUnitFilter&quot;">​</a></h2><p>单位过滤器可以分为两部分：<code>baseUnitFilter</code>s 和 <code>mapUnitFilter</code>s。 前者根据单位在 json 中出现的样子进行测试。 这意味着它没有拥有它的文明或它所站的地块，只是它的基本属性。 后者根据单位在地图上出现的样子进行测试，包括它的文明、地块、生命值和所有其他属性。</p><p>允许的值：</p><ul><li>单位名称</li><li>单位类型 - 例如 Melee、Ranged、WaterSubmarine 等</li><li><code>Land</code>、<code>Water</code>、<code>Air</code></li><li><code>land units</code>、<code>water units</code>、<code>air units</code></li><li><code>non-air</code> 用于非空中非导弹单位</li><li><code>Military</code>、<code>military units</code></li><li><code>Civilian</code>、<code>civilian units</code></li><li><code>All</code>、<code>all</code></li><li><code>Melee</code></li><li><code>Ranged</code></li><li><code>Nuclear Weapon</code></li><li><code>Great Person</code></li><li><code>Embarked</code></li><li>匹配该单位所需的 <a href="#technologyfilter">technologyfilter</a> - 例如 <code>Modern Era</code></li><li>单位拥有的任何精确 unique</li><li>单位类型拥有的任何精确 unique</li><li>上述任何组合（仅在所有匹配时才匹配）。格式是 <code>{filter1} {filter2}</code> 并且可以匹配任意数量的过滤器。例如：<code>[{Modern era} {Land}]</code> units</li></ul><h2 id="mapunitfilter" tabindex="-1">mapUnitFilter <a class="header-anchor" href="#mapunitfilter" aria-label="Permalink to &quot;mapUnitFilter&quot;">​</a></h2><p>这指示放置在地图上的单位。与 <code>baseUnitFilter</code> 比较。</p><p>允许的值：</p><ul><li>任何匹配的 <a href="#baseunitfilter">baseUnitFilter</a></li><li>任何匹配拥有者的 <a href="#civfilter">civFilter</a></li><li>单位拥有的任何 unique - 还包括 <a href="#baseunitfilter">baseUnitFilter</a> 未捕获的 uniques，例如晋升</li><li>任何晋升名称，或晋升拥有的精确 unique</li><li><code>Wounded</code></li><li><code>Embarked</code></li><li><code>City-State</code></li><li><code>Barbarians</code>、<code>Barbarian</code></li><li><code>Non-City</code></li><li>同样，上述任何组合也是允许的，例如 <code>[{Wounded} {Water}]</code> units。</li></ul><p>你可以在游戏中使用控制台通过 <code>unit checkfilter &lt;filter&gt;</code> 命令检查这一点</p><h2 id="buildingfilter" tabindex="-1">buildingFilter <a class="header-anchor" href="#buildingfilter" aria-label="Permalink to &quot;buildingFilter&quot;">​</a></h2><p>允许仅对特定建筑激活 unique。</p><p>允许的值：</p><ul><li><code>All</code>、<code>all</code></li><li><code>Buildings</code>、<code>Building</code></li><li><code>Wonder</code>、<code>Wonders</code></li><li><code>National Wonder</code>、<code>National</code></li><li><code>World Wonder</code>、<code>World</code> -- 所有不是国家奇观的奇观</li><li>建筑名称</li><li>它替换的建筑的名称（因此，例如图书馆的 uniques 也将适用于造纸厂）</li><li>匹配该建筑所需的 <a href="#technologyfilter">technologyfilter</a> - 例如 Modern Era</li><li>建筑拥有的精确 unique（例如：<code>spaceship part</code>）</li><li><code>Culture</code>、<code>Gold</code> 等，如果建筑对于该统计是 <code>stat-related</code>。Stat-related 建筑定义为以下之一： <ul><li>直接提供该统计（例如 +1 Culture）</li><li>为该统计提供百分比加成（例如 +10% Production）</li><li>作为资源的奖励提供该统计（例如每小麦 +1 Food）</li><li>为一定数量的人口提供该统计（例如每 2 人口 +1 Science [cityFilter]）</li></ul></li><li>上述任何组合（仅在所有匹配时才匹配）。格式是 <code>{filter1} {filter2}</code> 最多任意数量的过滤器。例如 <code>[{Ancient era} {Food}]</code> buildings。</li></ul><h2 id="cityfilter" tabindex="-1">cityFilter <a class="header-anchor" href="#cityfilter" aria-label="Permalink to &quot;cityFilter&quot;">​</a></h2><p>cityFilters 允许我们选择受此 unique 影响的城市范围：</p><ul><li><code>in this city</code></li><li><code>in all cities</code>、<code>All</code>、<code>all</code> - 通常适用于相关文明拥有的所有城市</li><li><code>in your cities</code>、<code>Your</code></li><li><code>in all coastal cities</code>、<code>Coastal</code></li><li><code>in capital</code>、<code>Capital</code></li><li><code>in all non-occupied cities</code>、<code>Non-occupied</code> - 所有不是傀儡且没有因最近被征服而产生额外不快乐的城市</li><li><code>in all cities with a world wonder</code></li><li><code>in all cities connected to capital</code></li><li><code>in all cities with a garrison</code>、<code>Garrisoned</code></li><li><code>in non-enemy foreign cities</code> - 在除你之外的其他文明拥有的、你没有与之交战的所有城市中</li><li><code>in enemy cities</code>、<code>Enemy</code></li><li><code>in foreign cities</code>、<code>Foreign</code></li><li><code>in annexed cities</code>、<code>Annexed</code></li><li><code>in puppeted cities</code>、<code>Puppeted</code></li><li><code>in resisting cities</code>、<code>Resisting</code></li><li><code>in cities being razed</code>、<code>Razing</code></li><li><code>in holy cities</code>、<code>Holy</code></li><li><code>in City-State cities</code></li><li><code>in cities following this religion</code> - 应仅用于宗教的万神殿/信徒 uniques</li><li><code>in cities following our religion</code></li><li><code>in all cities in which the majority religion is a major religion</code></li><li><code>in all cities in which the majority religion is an enhanced religion</code></li><li>[civFilter]</li></ul><p>你可以在游戏中使用控制台通过 <code>city checkfilter &lt;filter&gt;</code> 命令检查这一点</p><h2 id="erafilter" tabindex="-1">eraFilter <a class="header-anchor" href="#erafilter" aria-label="Permalink to &quot;eraFilter&quot;">​</a></h2><p>用于过滤特定时代。</p><p>允许的值：</p><ul><li>时代名称（例如：<code>Modern era</code>）</li><li><code>any era</code></li><li><code>Starting Era</code> - 游戏开始的时代</li><li><code>pre-[era]</code> - 出现在给定时代之前的任何时代（例如：<code>pre-[Modern era]</code>）</li><li><code>post-[era]</code> - 出现在给定时代之后的任何时代（例如：<code>post-[Ancient era]</code>）</li></ul><h2 id="improvementfilter" tabindex="-1">improvementFilter <a class="header-anchor" href="#improvementfilter" aria-label="Permalink to &quot;improvementFilter&quot;">​</a></h2><p>用于过滤特定的改良设施。</p><p>允许的值：</p><ul><li>改良设施名称</li><li>改良设施拥有的精确 unique（例如：<code>spaceship improvement</code>）</li><li><code>Improvement</code></li><li><code>All</code>、<code>all</code></li><li><code>Great Improvement</code>、<code>Great</code></li><li><code>All Road</code> - 用于道路和铁路</li></ul><h2 id="populationfilter" tabindex="-1">populationFilter <a class="header-anchor" href="#populationfilter" aria-label="Permalink to &quot;populationFilter&quot;">​</a></h2><p>确定城市人口一部分的过滤器。</p><p>允许的值：</p><ul><li><code>Population</code></li><li><code>Specialists</code></li><li><code>Unemployed</code></li><li><code>Followers of the Majority Religion</code> 或 <code>Followers of this Religion</code>，两者仅当该宗教是城市中的多数宗教时才适用</li><li>专家名称</li></ul><h2 id="religionfilter" tabindex="-1">religionFilter <a class="header-anchor" href="#religionfilter" aria-label="Permalink to &quot;religionFilter&quot;">​</a></h2><p>用于过滤特定宗教</p><ul><li><code>any</code></li><li><code>major</code></li><li><code>enhanced</code></li><li><code>your</code></li><li><code>foreign</code></li><li><code>enemy</code></li><li>宗教符号的名称</li><li>信仰的名称</li><li>宗教拥有的信仰的 unique</li></ul><h2 id="policyfilter" tabindex="-1">policyFilter <a class="header-anchor" href="#policyfilter" aria-label="Permalink to &quot;policyFilter&quot;">​</a></h2><p>允许的值：</p><ul><li><code>All</code>、<code>all</code></li><li><code>[policyBranchName] branch</code></li><li>政策的名称</li><li>政策拥有的 unique（逐字，没有占位符）</li></ul><h2 id="combatantfilter" tabindex="-1">combatantFilter <a class="header-anchor" href="#combatantfilter" aria-label="Permalink to &quot;combatantFilter&quot;">​</a></h2><p>允许的值：</p><ul><li><a href="#mapunitfilter">mapUnitFilter</a>，用于单位战斗者</li><li><code>City</code>、<code>All</code> 或 <a href="#civfilter">civFilter</a>，用于城市战斗者</li></ul><p>由于 mapUnitFilter 包含 civFilter，这意味着 civFilter 可以应用于单位和城市的 combatantFilter。</p><h2 id="regiontype" tabindex="-1">regionType <a class="header-anchor" href="#regiontype" aria-label="Permalink to &quot;regionType&quot;">​</a></h2><p>用于在游戏开始时将世界划分为区域，每个区域放置单个玩家。 允许的值是 <code>Hybrid</code> 和任何具有以下两个 uniques 之一的地形的名称：</p><ul><li><code>A Region is formed with at least [amount]% [simpleTerrain] tiles, with priority [amount]</code></li><li><code>A Region is formed with at least [amount]% [simpleTerrain] tiles and [simpleTerrain] tiles, with priority [amount]</code></li></ul><h2 id="simpleterrain" tabindex="-1">simpleTerrain <a class="header-anchor" href="#simpleterrain" aria-label="Permalink to &quot;simpleTerrain&quot;">​</a></h2><p>由 NaturalWonderGenerator 用于放置自然奇观</p><p>允许的值：</p><ul><li><code>Land</code></li><li><code>Water</code></li><li><code>Elevated</code></li><li>任何地形的名称</li></ul><h2 id="stats" tabindex="-1">stats <a class="header-anchor" href="#stats" aria-label="Permalink to &quot;stats&quot;">​</a></h2><p>这指示由特定统计组成的文本，稍微复杂一些。</p><p>每个统计由几个统计变化组成，每个变化形式为 <code>+{amount} {stat}</code>， 其中&#39;stat&#39;是七个主要统计之一 （例如 <code>Production</code>、<code>Food</code>、<code>Gold</code>、<code>Science</code>、<code>Culture</code>、<code>Happiness</code> 和 <code>Faith</code>）。 例如：<code>+1 Science</code>。</p><p>这些可以用 &quot;, &quot; 串在一起，例如：<code>+2 Production, +3 Food</code>。</p><h2 id="resourcefilter" tabindex="-1">resourceFilter <a class="header-anchor" href="#resourcefilter" aria-label="Permalink to &quot;resourceFilter&quot;">​</a></h2><p>允许的值：</p><ul><li>资源名称</li><li><code>any</code></li><li><code>All</code>、<code>all</code></li><li>资源类型：<code>Strategic</code>、<code>Luxury</code>、<code>Bonus</code></li><li>改良时提供的统计（例如 <code>Food</code>）</li></ul><h2 id="stockpiledresource" tabindex="-1">stockpiledResource <a class="header-anchor" href="#stockpiledresource" aria-label="Permalink to &quot;stockpiledResource&quot;">​</a></h2><p>这指示对应于自定义库存资源的文本。</p><p>这些是全局文明资源，作用类似于主要的文明范围的资源，如 <code>Gold</code> 和 <code>Faith</code>。 你可以生成它们并消耗它们。如果你库存中没有足够的数量，消耗它们的操作将被阻止。</p><p>要使用，你需要首先定义一个具有&quot;Stockpilled&quot; Unique 的 TileResources。然后你可以在其他 Uniques 中引用它们。</p><h2 id="stockpile" tabindex="-1">Stockpile <a class="header-anchor" href="#stockpile" aria-label="Permalink to &quot;Stockpile&quot;">​</a></h2><p>可以添加到文明的东西</p><p>允许的值：</p><ul><li>库存资源（见上文）</li><li>统计名称 - 用于全局统计，不是城市统计</li><li><code>Stored Food</code>（用于城市）</li><li><code>Golden Age points</code></li></ul><h2 id="technologyfilter" tabindex="-1">technologyFilter <a class="header-anchor" href="#technologyfilter" aria-label="Permalink to &quot;technologyFilter&quot;">​</a></h2><p>目前仅针对 <a href="/Unciv/zh/Modders/Mod-file-structure/5-Miscellaneous-JSON-files.html#modoptions-json">ModOptions.techsToRemove</a>实现。</p><p>允许的值：</p><ul><li><code>All</code>、<code>all</code></li><li>匹配科技时代的 <a href="#erafilter">eraFilter</a></li><li>科技的名称</li><li>科技拥有的 unique（逐字，没有占位符）</li></ul><h2 id="terrainfilter" tabindex="-1">terrainFilter <a class="header-anchor" href="#terrainfilter" aria-label="Permalink to &quot;terrainFilter&quot;">​</a></h2><p>这指示单个地块上的地形。</p><p>允许的值：</p><ul><li>过滤器命名特定的 json 属性（按名称）： <ul><li>基础地形</li><li>地形特征</li><li>基础地形 uniques</li><li>地形特征 uniques</li><li>资源</li><li>自然奇观</li><li>匹配地块拥有者的 <a href="#nationfilter">nationFilter</a></li></ul></li><li>或者过滤器是选择派生测试的常量字符串： <ul><li><code>All</code>、<code>all</code></li><li><code>Terrain</code></li><li><code>Water</code>、<code>Land</code></li><li><code>Coastal</code>（至少一个直接邻居是海岸）</li><li><code>River</code>（在所有&#39;地块上的河流&#39;上下文中，意味着&#39;至少一侧与河流相邻&#39;）</li><li><code>Open terrain</code>、<code>Rough terrain</code>（注意所有没有 rough unique 的地形都算作开放）</li><li><code>Friendly Land</code>、<code>Friendly</code> - 属于你的土地，或对你有开放边界的其他文明</li><li><code>Foreign Land</code> - 任何不是友好土地的土地</li><li><code>Enemy Land</code>、<code>Enemy</code> - 任何属于你与之交战的文明的土地</li><li><code>your</code> - 属于你的土地</li><li><code>Unowned</code> - 不被任何文明拥有的土地</li><li><code>Water resource</code>、<code>Strategic resource</code>、<code>Luxury resource</code>、<code>Bonus resource</code>、<code>resource</code></li><li><code>Natural Wonder</code>（与上面相反，后者意味着按名称测试特定的自然奇观，这测试任何自然奇观）</li><li><code>Featureless</code></li><li><code>Fresh Water</code></li><li><code>non-fresh water</code></li><li><code>Impassible</code></li></ul></li></ul><p>请注意所有这些都区分大小写。</p><p>注意：资源过滤器取决于在过滤器运行的上下文中是否已知查看文明。水和特定测试需要查看文明，并且如果资源需要科技才能可见，则该科技必须由查看文明研究。其他资源类别测试只有在资源不需要任何科技的情况下才能在没有已知查看文明的情况下成功。所以 - 测试你的模组！</p><p>例如，unique &quot;[stats] from [tileFilter] tiles [cityFilter]&quot; 可以匹配几种情况：</p><h2 id="tilefilter" tabindex="-1">tileFilter <a class="header-anchor" href="#tilefilter" aria-label="Permalink to &quot;tileFilter&quot;">​</a></h2><p>允许的值：</p><ul><li>该地块的 <a href="#terrainfilter">terrainFilter</a></li><li>该地块的 <a href="#improvementfilter">improvementFilter</a></li><li>拥有该地块的文明的 <a href="#civfilter">civFilter</a></li><li><code>Improvement</code> 或 <code>improved</code> 用于有任何改良设施的地块</li><li><code>unimproved</code> 用于没有改良设施的地块</li><li><code>pillaged</code> 用于被掠夺的地块</li><li><code>worked</code> 用于被城市工作的地块</li></ul><p>你可以在游戏中使用控制台通过 <code>tile checkfilter &lt;filter&gt;</code> 命令检查这一点</p><h2 id="terrainquality" tabindex="-1">terrainQuality <a class="header-anchor" href="#terrainquality" aria-label="Permalink to &quot;terrainQuality&quot;">​</a></h2><p>用于指示在将世界划分为区域时，应该将地形用于什么用途，每个区域在游戏开始时放置单个玩家。</p><p>允许的值：</p><ul><li><code>Undesirable</code></li><li><code>Food</code></li><li><code>Desirable</code></li><li><code>Production</code></li></ul><h2 id="countable" tabindex="-1">countable <a class="header-anchor" href="#countable" aria-label="Permalink to &quot;countable&quot;">​</a></h2><p>指示<em>可以计数的东西</em>，用于比较和乘法 uniques</p><p>允许的值：</p><ul><li>整数常量 - 任何正整数或负整数 <ul><li>示例：<code>Only available &lt;when number of [123] is more than [0]&gt;</code></li></ul></li><li><code>turns</code> - 已进行的回合数 <ul><li>示例：<code>Only available &lt;when number of [turns] is more than [0]&gt;</code></li><li>无论游戏速度或开始时代如何，始终从零开始</li></ul></li><li><code>year</code> - 当前年份 <ul><li>示例：<code>Only available &lt;when number of [year] is more than [0]&gt;</code></li><li>取决于游戏速度或开始时代，公元前年份为负数</li></ul></li><li><code>Cities</code> - 相关文明拥有的城市数量 <ul><li>示例：<code>Only available &lt;when number of [Cities] is more than [0]&gt;</code></li></ul></li><li><code>Units</code> - 相关文明拥有的单位数量 <ul><li>示例：<code>Only available &lt;when number of [Units] is more than [0]&gt;</code></li></ul></li><li><code>City Population</code> - 相关城市的人口 <ul><li>示例：<code>Only available &lt;when number of [City Population] is more than [0]&gt;</code></li></ul></li><li><code>Total Population</code> - 相关文明的总人口 <ul><li>示例：<code>Only available &lt;when number of [Total Population] is more than [0]&gt;</code></li></ul></li><li><code>Unit Health</code> - 相关单位的当前生命值（0-100） <ul><li>示例：<code>Only available &lt;when number of [Unit Health] is more than [0]&gt;</code></li></ul></li><li><code>Unit Experience</code> - 相关单位累计的经验 <ul><li>示例：<code>Only available &lt;when number of [Unit Experience] is more than [0]&gt;</code></li></ul></li><li><code>Unit Level</code> - 相关单位的等级（晋升次数 + 1） <ul><li>示例：<code>Only available &lt;when number of [Unit Level] is more than [0]&gt;</code></li></ul></li><li><code>Golden Age Points</code> - 为下一次黄金时代累积的笑脸点数 <ul><li>示例：<code>Only available &lt;when number of [Golden Age Points] is more than [0]&gt;</code></li></ul></li><li><code>Golden Age Turns</code> - 当前黄金时代剩余回合数 <ul><li>示例：<code>Only available &lt;when number of [Golden Age Turns] is more than [0]&gt;</code></li></ul></li><li><code>Researched Technologies</code> - 相关文明已研究的科技数量 <ul><li>示例：<code>Only available &lt;when number of [Researched Technologies] is more than [0]&gt;</code></li></ul></li><li><code>Adopted Policies</code> - 相关文明已采用的政策数量 <ul><li>示例：<code>Only available &lt;when number of [Adopted Policies] is more than [0]&gt;</code></li></ul></li><li><code>City Strength</code> - 相关城市的战斗强度 <ul><li>示例：<code>Only available &lt;when number of [City Strength] is more than [0]&gt;</code></li></ul></li><li>统计名称（<code>Production</code>, <code>Food</code>, <code>Gold</code>, <code>Science</code>, <code>Culture</code>, <code>Happiness</code> or <code>Faith</code>） <ul><li>示例：<code>Only available &lt;when number of [Science] is more than [0]&gt;</code></li><li>获取统计<em>储备</em>，而不是每回合的数量（可以是城市统计或文明统计，取决于 unique 在何处使用）</li></ul></li><li>统计/资源每回合 <ul><li>示例：<code>Only available &lt;when number of [[Culture] Per Turn] is more than [0]&gt;</code></li><li>获取文明每回合获得的统计或资源数量</li></ul></li><li><code>Completed Policy branches</code><ul><li>示例：<code>Only available &lt;when number of [Completed Policy branches] is more than [0]&gt;</code></li></ul></li><li><code>[cityFilter] Cities</code><ul><li>示例：<code>Only available &lt;when number of [[in all cities] Cities] is more than [0]&gt;</code></li></ul></li><li><code>[mapUnitFilter] Units</code><ul><li>示例：<code>Only available &lt;when number of [[Wounded] Units] is more than [0]&gt;</code></li></ul></li><li><code>Carried [mapUnitFilter] units</code> - 该单位携带的单位数量 <ul><li>示例：<code>Only available &lt;when number of [Carried [Air] units] is more than [0]&gt;</code></li><li>仅计算匹配过滤器的运输单位。用于 &#39;when number of&#39; 条件。</li></ul></li><li><code>[buildingFilter] Buildings</code><ul><li>示例：<code>Only available &lt;when number of [[Culture] Buildings] is more than [0]&gt;</code></li></ul></li><li><code>[buildingFilter] Buildings by [civFilter] Civilizations</code><ul><li>示例：<code>Only available &lt;when number of [[Culture] Buildings by [City-States] Civilizations] is more than [0]&gt;</code></li></ul></li><li><code>[cityFilter] Cities of [civFilter] Civilizations</code><ul><li>示例：<code>Only available &lt;when number of [[in all cities] Cities of [City-States] Civilizations] is more than [0]&gt;</code></li></ul></li><li><code>Adopted [policyFilter] Policies</code><ul><li>示例：<code>Only available &lt;when number of [Adopted [Oligarchy] Policies] is more than [0]&gt;</code></li></ul></li><li><code>Adopted [policyFilter] Policies by [civFilter] Civilizations</code><ul><li>示例：<code>Only available &lt;when number of [Adopted [Oligarchy] Policies by [City-States] Civilizations] is more than [0]&gt;</code></li></ul></li><li><code>Researched [techFilter] Technologies</code><ul><li>示例：<code>Only available &lt;when number of [Researched [Agriculture] Technologies] is more than [0]&gt;</code></li><li>统计相关文明已研究的匹配科技</li><li>可重复科技（如未来科技）只计一次</li></ul></li><li><code>Remaining [civFilter] Civilizations</code><ul><li>示例：<code>Only available &lt;when number of [Remaining [City-States] Civilizations] is more than [0]&gt;</code></li></ul></li><li><code>Worked [tileFilter] Tiles in this city</code><ul><li>示例：<code>Only available &lt;when number of [Worked [Farm] Tiles in this city] is more than [0]&gt;</code></li></ul></li><li><code>Worked [tileFilter] Tiles</code><ul><li>示例：<code>Only available &lt;when number of [Worked [Farm] Tiles] is more than [0]&gt;</code></li></ul></li><li><code>Owned [tileFilter] Tiles</code><ul><li>示例：<code>Only available &lt;when number of [Owned [Farm] Tiles] is more than [0]&gt;</code></li></ul></li><li><code>[tileFilter] Tiles</code><ul><li>示例：<code>Only available &lt;when number of [[Desert] Tiles] is more than [0]&gt;</code></li></ul></li><li>资源名称 - 来自 <a href="/Unciv/zh/Modders/Mod-file-structure/3-Map-related-JSON-files.html#tileresources-json">TileResources.json</a><ul><li>示例：<code>Only available &lt;when number of [Iron] is more than [0]&gt;</code></li><li>可以是城市统计或文明统计，取决于 unique 在何处使用</li><li>例如：如果 unique 放在建筑上，获取的资源属于城市；如果放在政策上，则属于文明。</li><li>这对例如按城市计数的本地资源会有影响。</li></ul></li><li><code>[resourceFilter] resource of [civFilter] Civilizations</code><ul><li>示例：<code>Only available &lt;when number of [[Strategic] resource of [City-States] Civilizations] is more than [0]&gt;</code></li></ul></li><li><code>Era number</code> - 当前玩家所处时代的编号 <ul><li>示例：<code>Only available &lt;when number of [Era number] is more than [0]&gt;</code></li><li>Eras.json 中时代的从零开始的索引。</li></ul></li><li><code>Speed modifier for [stat]</code> - 特定产出的游戏速度修正，以百分比表示 <ul><li>示例：<code>Only available &lt;when number of [Speed modifier for [Culture]] is more than [0]&gt;</code></li><li>从玩家选择的 Speeds.json 条目中选择合适的字段。</li><li>返回值乘以 100。</li><li>食物和笑脸返回通用的 <code>modifier</code> 字段。</li><li>其他字段如 <code>goldGiftModifier</code> 或 <code>barbarianModifier</code> 不能通过此 Countable 访问。</li></ul></li><li>评估表达式！ <ul><li>示例：<code>Only available &lt;when number of [[Iron] + 2] is more than [0]&gt;</code></li><li>表达式支持任意数学运算，用方括号包围时可以包含其他 countable。</li><li>例如，<code>Cities</code> 是 countable，<code>[Melee] units</code> 也是 countable，你可以写类似：<code>([[Melee] units] + 1) / [Cities]</code>（空格可选，但有助于阅读）</li><li>由于翻译时会移除方括号，表达式将显示为 <code>(Melee units + 1) / Cities</code></li><li>2 个值之间支持的操作是：+、-、*、/、%、^</li><li>1 个值上支持的操作是：-（否定）、√（平方根）、abs（绝对值 - 将负数变为正数）、sqrt（平方根）、floor（向下取整）、ceil（向上取整）</li><li>支持的函数：</li><li><ul><li><code>max(expression,expression,...)</code></li></ul></li><li><ul><li><code>min(expression,expression,...)</code></li></ul></li></ul></li></ul>',106)])])}const m=i(c,[["render",t]]);export{p as __pageData,m as default};
